-- Ses odası sıralaması: bu hafta oyunda harcanan coin.
-- Hediye değil; odada oynanan oyunların bahis toplamı.

create table if not exists public.oda_oyun_harcama (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references public.rooms(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  spent_coin bigint not null check (spent_coin > 0),
  created_at timestamptz not null default now()
);

create index if not exists oda_oyun_harcama_room_created_idx
  on public.oda_oyun_harcama (room_id, created_at desc);

alter table public.oda_oyun_harcama enable row level security;

revoke all on public.oda_oyun_harcama from public, anon, authenticated;

create or replace function public.kullanici_canli_odasi(p_user uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select rm.room_id
  from public.room_members rm
  join public.rooms r on r.id = rm.room_id
  where rm.user_id = p_user
    and coalesce(r.is_live, false) = true
  order by rm.joined_at desc
  limit 1;
$$;

revoke all on function public.kullanici_canli_odasi(uuid) from public, anon, authenticated;

create or replace function public.oda_oyun_coin_ekle(
  p_room_id uuid,
  p_user_id uuid,
  p_won bigint default 0,
  p_spent bigint default 0
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_spent bigint := greatest(coalesce(p_spent, 0), 0);
  v_won bigint := greatest(coalesce(p_won, 0), 0);
begin
  if p_room_id is null or p_user_id is null then return; end if;
  if v_won <= 0 and v_spent <= 0 then return; end if;

  insert into public.oda_oyun_coin_istatistik (room_id, user_id, won_coin, spent_coin)
  values (p_room_id, p_user_id, v_won, v_spent)
  on conflict (room_id, user_id) do update set
    won_coin = oda_oyun_coin_istatistik.won_coin + excluded.won_coin,
    spent_coin = oda_oyun_coin_istatistik.spent_coin + excluded.spent_coin,
    updated_at = now();

  if v_spent > 0 then
    insert into public.oda_oyun_harcama (room_id, user_id, spent_coin)
    values (p_room_id, p_user_id, v_spent);
  end if;
end;
$$;

revoke all on function public.oda_oyun_coin_ekle(uuid, uuid, bigint, bigint) from public, anon, authenticated;
grant execute on function public.oda_oyun_coin_ekle(uuid, uuid, bigint, bigint) to service_role;

-- Geçmiş oda harcaması bu haftanın sıralamasına girsin.
insert into public.oda_oyun_harcama (room_id, user_id, spent_coin, created_at)
select s.room_id, s.user_id, s.spent_coin, now()
from public.oda_oyun_coin_istatistik s
where s.spent_coin > 0
  and not exists (
    select 1 from public.oda_oyun_harcama h
    where h.room_id = s.room_id and h.user_id = s.user_id
  );

create or replace function public.fruit_wheel_oda_harcama_yaz()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_spent bigint := greatest(-coalesce(new.delta, 0), 0);
  v_room uuid;
begin
  if v_spent <= 0 then
    return new;
  end if;
  v_room := public.kullanici_canli_odasi(new.user_id);
  if v_room is not null then
    perform public.oda_oyun_coin_ekle(v_room, new.user_id, 0, v_spent);
  end if;
  return new;
end;
$$;

revoke all on function public.fruit_wheel_oda_harcama_yaz() from public, anon, authenticated;

drop trigger if exists fruit_wheel_commands_oda_harcama on public.fruit_wheel_commands;
create trigger fruit_wheel_commands_oda_harcama
  after insert on public.fruit_wheel_commands
  for each row
  execute function public.fruit_wheel_oda_harcama_yaz();

create or replace function public.liderlik_siralamasi_yenile(
  p_board_type text,
  p_period text default 'daily'
)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  v_period text := lower(coalesce(nullif(trim(p_period), ''), 'daily'));
  v_key text := public.liderlik_period_key(v_period);
  v_start timestamptz := public.liderlik_period_baslangic(v_period);
  v_count int := 0;
begin
  if v_period not in ('daily', 'weekly', 'monthly', 'all_time') then
    raise exception 'Gecersiz period';
  end if;

  if p_board_type = 'gifter' then
    delete from public.leaderboard_snapshots
    where board_type = 'gifter' and period = v_period and period_key = v_key;

    if v_period = 'all_time' then
      insert into public.leaderboard_snapshots (board_type, period, period_key, user_id, score, rank)
      select 'gifter', v_period, v_key, s.user_id, s.total_spent_coin,
        row_number() over (order by s.total_spent_coin desc)
      from public.user_profile_stats s
      left join public.user_privacy_settings pr on pr.user_id = s.user_id
      where s.total_spent_coin > 0
        and coalesce(pr.hide_gifter_rank, false) = false
      order by s.total_spent_coin desc
      limit 100;
    else
      insert into public.leaderboard_snapshots (board_type, period, period_key, user_id, score, rank)
      select 'gifter', v_period, v_key, g.sender_id, sum(g.coins_spent)::bigint,
        row_number() over (order by sum(g.coins_spent) desc)
      from public.gift_transactions g
      left join public.user_privacy_settings pr on pr.user_id = g.sender_id
      where g.created_at >= v_start
        and coalesce(pr.hide_gifter_rank, false) = false
      group by g.sender_id
      having sum(g.coins_spent) > 0
      order by sum(g.coins_spent) desc
      limit 100;
    end if;
    get diagnostics v_count = row_count;

  elsif p_board_type = 'top_recharge' then
    delete from public.leaderboard_snapshots
    where board_type = 'top_recharge' and period = v_period and period_key = v_key;

    if v_period = 'all_time' then
      insert into public.leaderboard_snapshots (board_type, period, period_key, user_id, score, rank)
      select 'top_recharge', v_period, v_key, s.user_id, s.total_topup_coin,
        row_number() over (order by s.total_topup_coin desc)
      from public.user_profile_stats s
      left join public.user_privacy_settings pr on pr.user_id = s.user_id
      where s.total_topup_coin > 0
        and coalesce(pr.hide_recharge_rank, false) = false
      order by s.total_topup_coin desc
      limit 100;
    else
      insert into public.leaderboard_snapshots (board_type, period, period_key, user_id, score, rank)
      select 'top_recharge', v_period, v_key, c.user_id, sum(c.coins_added)::bigint,
        row_number() over (order by sum(c.coins_added) desc)
      from public.coin_purchases c
      left join public.user_privacy_settings pr on pr.user_id = c.user_id
      where c.status = 'completed'
        and c.created_at >= v_start
        and coalesce(pr.hide_recharge_rank, false) = false
      group by c.user_id
      having sum(c.coins_added) > 0
      order by sum(c.coins_added) desc
      limit 100;
    end if;
    get diagnostics v_count = row_count;

  elsif p_board_type = 'host' then
    delete from public.leaderboard_snapshots
    where board_type = 'host' and period = v_period and period_key = v_key;

    insert into public.leaderboard_snapshots (board_type, period, period_key, user_id, score, rank)
    select 'host', v_period, v_key, s.user_id, s.total_gifts_received,
      row_number() over (order by s.total_gifts_received desc)
    from public.user_profile_stats s
    where s.total_gifts_received > 0
    order by s.total_gifts_received desc
    limit 100;
    get diagnostics v_count = row_count;

  elsif p_board_type = 'room' then
    delete from public.leaderboard_snapshots
    where board_type = 'room' and period = v_period and period_key = v_key;

    insert into public.leaderboard_snapshots (
      board_type, period, period_key, user_id, room_id, score, rank
    )
    select
      'room', v_period, v_key, r.host_id, x.room_id, x.skor,
      row_number() over (order by x.skor desc)
    from (
      select h.room_id, sum(h.spent_coin)::bigint as skor
      from public.oda_oyun_harcama h
      where h.spent_coin > 0
        and (v_period = 'all_time' or h.created_at >= v_start)
      group by h.room_id
      having sum(h.spent_coin) > 0
    ) x
    join public.rooms r on r.id = x.room_id
    where r.host_id is not null
    order by x.skor desc
    limit 100;
    get diagnostics v_count = row_count;
  end if;

  return v_count;
end;
$$;

grant execute on function public.liderlik_siralamasi_yenile(text, text) to authenticated;

-- Sis Spin bahsi, oyuncu canlı bir ses odasındaysa o odaya yazılsın.
create or replace function public.sis_spin_cevir(p_bet bigint)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_coins bigint;
  v_roll int;
  v_id int;
  v_mult numeric;
  v_label text;
  v_payout bigint;
  v_after bigint;
  v_room uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if p_bet not in (10, 50, 100, 250, 500, 1000) then
    raise exception 'Invalid bet';
  end if;

  if public.kill_switch_aktif_mi('kill_games') then
    raise exception 'Games temporarily disabled';
  end if;
  if public.kill_switch_aktif_mi('kill_game_coin') then
    raise exception 'Game coin disabled';
  end if;

  select coins into v_coins
  from public.wallets
  where user_id = v_uid
  for update;

  if v_coins is null then
    raise exception 'Wallet not found';
  end if;
  if v_coins < p_bet then
    raise exception 'Insufficient coins';
  end if;

  v_roll := floor(random() * 100)::int;

  if v_roll < 38 then
    v_id := 0; v_mult := 0; v_label := '0';
  elsif v_roll < 60 then
    v_id := 1; v_mult := 0.5; v_label := '0.5x';
  elsif v_roll < 80 then
    v_id := 2; v_mult := 1; v_label := '1x';
  elsif v_roll < 92 then
    v_id := 3; v_mult := 2; v_label := '2x';
  elsif v_roll < 96 then
    v_id := 4; v_mult := 3; v_label := '3x';
  elsif v_roll < 98 then
    v_id := 5; v_mult := 5; v_label := '5x';
  elsif v_roll < 99 then
    v_id := 6; v_mult := 8; v_label := '8x';
  else
    v_id := 7; v_mult := 10; v_label := '10x';
  end if;

  v_payout := floor(p_bet * v_mult)::bigint;
  v_after := v_coins - p_bet + v_payout;

  update public.wallets
  set coins = v_after,
      updated_at = now()
  where user_id = v_uid;

  v_room := public.kullanici_canli_odasi(v_uid);
  if v_room is not null then
    perform public.oda_oyun_coin_ekle(v_room, v_uid, v_payout, p_bet);
  end if;

  if v_payout > 0 then
    perform public.oyun_kazanc_duyuru_yaz(
      v_uid,
      v_room,
      'sis_spin',
      'Sis Spin',
      v_payout,
      p_bet,
      null,
      v_mult
    );
  end if;

  return jsonb_build_object(
    'segmentId', v_id,
    'label', v_label,
    'multiplier', v_mult,
    'bet', p_bet,
    'payout', v_payout,
    'balanceBefore', v_coins,
    'balanceAfter', v_after
  );
end;
$$;

revoke all on function public.sis_spin_cevir(bigint) from public;
grant execute on function public.sis_spin_cevir(bigint) to authenticated;

select public.liderlik_siralamasi_yenile('room', 'weekly');
